import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap, Tooltip, ZoomControl } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./FloodMap.css";
import kaladyRiver from "../assets/kalady-river.png";

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const ITEMS_PER_PAGE = 10;

// Top of the staff gauge shown in the hero, in metres. Display only.
const GAUGE_MAX = 12;

// 🎨 HELPER: Risk Color Logic
const getRiskStatus = (depth, isNormalState) => {
  if (isNormalState) {
    return {
      color: "#10b981",
      bg: "rgba(16, 185, 129, 0.1)",
      label: "Safe / Normal Flow",
      icon: "fa-check-circle",
      shadow: "0 4px 14px 0 rgba(16, 185, 129, 0.39)"
    };
  }

  if (depth <= 3) return { color: "#10b981", bg: "rgba(16, 185, 129, 0.1)", label: "Low Risk", icon: "fa-check-circle", shadow: "0 4px 14px 0 rgba(16, 185, 129, 0.39)" };
  if (depth < 8) return { color: "#f59e0b", bg: "rgba(245, 158, 11, 0.1)", label: "Moderate Risk", icon: "fa-exclamation-circle", shadow: "0 4px 14px 0 rgba(245, 158, 11, 0.39)" };
  return { color: "#ef4444", bg: "rgba(239, 68, 68, 0.1)", label: "Critical Risk", icon: "fa-exclamation-triangle", shadow: "0 4px 14px 0 rgba(239, 68, 68, 0.39)" };
};

const generateSmartName = (osmData) => {
  if (!osmData) return "Unknown Location";
  const addr = osmData.address || {};
  const street = addr.road || addr.street || addr.pedestrian || addr.path || addr.lane;
  const area = addr.neighbourhood || addr.suburb || addr.residential || addr.village;
  const town = addr.town || addr.city || addr.county;
  if (street && area) return `${street}, ${area}`;
  if (street && town) return `${street}, ${town}`;
  if (area && town) return `${area}, ${town}`;
  if (osmData.display_name) return osmData.display_name.split(", ").slice(0, 2).join(", ");
  return town || "Flood Point";
};

// 📍 COMPONENT: Map Popup
const LocationPopup = ({ lat, lon, depth, isNormalState }) => {
  const [address, setAddress] = useState("Loading details...");
  const [title, setTitle] = useState("Location Details");
  const status = getRiskStatus(depth, isNormalState);

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`;
        const res = await axios.get(url);
        if (res.data) {
          setTitle(generateSmartName(res.data));
          setAddress(res.data.display_name);
        }
      } catch (err) { setAddress("Address unavailable"); }
    };
    fetchAddress();
  }, [lat, lon]);

  return (
    <div style={{ minWidth: '230px' }}>
      <div className="fm-eyebrow" style={{ color: status.color, marginBottom: '4px' }}>{status.label}</div>
      <strong style={{ fontSize: '15px', color: '#0b2137', display: 'block', marginBottom: '10px' }}>{title}</strong>
      {!isNormalState && (
        <div style={{ background: '#eef2f5', padding: '8px 10px', borderRadius: '6px', marginBottom: '10px' }}>
          <span style={{ color: '#6b839a', fontSize: '11px' }}>Water depth</span>
          <strong className="fm-num" style={{ color: status.color, marginLeft: '6px', fontSize: '14px' }}>{depth}m</strong>
        </div>
      )}
      <div style={{ fontSize: '11px', color: '#6b839a', lineHeight: '1.5' }}>
        <i className="fas fa-map-marker-alt" style={{ marginRight: '5px' }}></i>
        {address}
      </div>
    </div>
  );
};

const MapController = ({ targetLoc }) => {
  const map = useMap();
  useEffect(() => {
    if (targetLoc) { map.flyTo(targetLoc, 14, { animate: true, duration: 1.5 }); }
  }, [targetLoc, map]);
  return null;
};

const CustomMapControls = ({ onSearch, onFindMe }) => {
  const [query, setQuery] = useState("");
  const [searching, setSearching] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;
    setSearching(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`);
      if (res.data && res.data.length > 0) {
        const { lat, lon } = res.data[0];
        onSearch([parseFloat(lat), parseFloat(lon)]);
      }
    } catch (err) { console.error(err); }
    finally { setSearching(false); }
  };

  return (
    <div className="custom-map-controls">
      <form onSubmit={handleSearch} className="search-form-overlay">
        <input
          type="text" value={query} onChange={(e) => setQuery(e.target.value)}
          placeholder="Search a place"
          aria-label="Search a place"
          className="search-input-leaflet"
        />
        <button type="submit" className="search-btn-leaflet" aria-label="Search">
          {searching ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-search"></i>}
        </button>
      </form>
      <button onClick={onFindMe} className="locate-btn-leaflet" aria-label="Go to my location">
        <i className="fas fa-location-arrow"></i>
      </button>
    </div>
  );
};

const MapLegend = () => (
  <div className="map-legend-overlay">
    <h5>Risk scale</h5>
    <div className="legend-rows">
      <div className="legend-row"><i style={{ background: '#ef4444' }}></i> Critical — 8m and above</div>
      <div className="legend-row"><i style={{ background: '#f59e0b' }}></i> Moderate — 3m to 8m</div>
      <div className="legend-row"><i style={{ background: '#10b981' }}></i> Low — under 3m</div>
    </div>
  </div>
);

const Pagination = ({ currentPage, totalItems, onPageChange }) => {
  const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
  if (totalPages <= 1) return null;
  return (
    <div className="fm-pagination">
      <button className="fm-btn fm-btn--ghost" onClick={() => onPageChange(currentPage - 1)} disabled={currentPage === 1}>Previous</button>
      <span className="page-count">{currentPage} / {totalPages}</span>
      <button className="fm-btn fm-btn--ghost" onClick={() => onPageChange(currentPage + 1)} disabled={currentPage === totalPages}>Next</button>
    </div>
  );
};

const AffectedAreaItem = ({ data, index }) => {
  const [expanded, setExpanded] = useState(false);
  const [details, setDetails] = useState(null);
  const [loading, setLoading] = useState(false);
  const [displayName, setDisplayName] = useState(data.place);
  const status = getRiskStatus(data.depth, false);

  const fetchDetails = async () => {
    if (details || loading) return;
    setLoading(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${data.lat}&lon=${data.lon}`);
      if (res.data) { setDetails(res.data); setDisplayName(generateSmartName(res.data)); }
    } catch (e) { setDetails({ error: true }); }
    finally { setLoading(false); }
  };

  return (
    <div className="rd-glass-card" style={{ marginBottom: '12px', borderLeft: `3px solid ${status.color}`, padding: '18px 20px' }}>
      <div className="area-row">
        <div className="area-id">
          <div className="area-badge" style={{ background: status.bg, color: status.color }}>
            <i className={`fas ${status.icon}`}></i>
          </div>
          <div style={{ minWidth: 0 }}>
            <h4 className="area-name">{displayName}</h4>
            <span className="area-meta">Depth <strong>{data.depth}m</strong> · {status.label}</span>
          </div>
        </div>
        <button
          className="fm-btn fm-btn--ghost"
          onClick={() => { if (!expanded) fetchDetails(); setExpanded(!expanded); }}
          aria-expanded={expanded}
        >
          {expanded ? 'Hide details' : 'Show details'}
        </button>
      </div>
      {expanded && (
        <div className="area-detail">
          {loading ? 'Looking up this location…' : details?.display_name || 'No address on record for these coordinates.'}
        </div>
      )}
    </div>
  );
};

const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);
  const [severePage, setSeverePage] = useState(1);
  const [otherPage, setOtherPage] = useState(1);
  const [showAllAreas, setShowAllAreas] = useState(false);
  const [mapCenter, setMapCenter] = useState([10.16, 76.43]);
  const [userPos, setUserPos] = useState(null);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, { params: { level: simulatedLevel } });
        if (response.data) {
          if (response.data.data) response.data.data.sort((a, b) => b.depth - a.depth);
          setFloodData(response.data);
        }
      } catch (error) { console.error(error); }
      finally { setLoading(false); }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  // 🖥️ CONSOLE: log risk zones whenever data changes
  useEffect(() => {
    if (!floodData?.data) return;

    const level = floodData.current_water_level || 3.5;

    if (level <= 3.0) {
      console.log(`%c✅ No risk zones — river at ${level}m (normal flow)`,
        'color:#10b981;font-weight:bold');
      return;
    }

    const risky = floodData.data
      .filter(d => d.depth >= level)
      .map((d, i) => ({
        '#': i + 1,
        Place: d.place || 'Unnamed',
        'Depth (m)': d.depth,
        Risk: d.depth <= 3 ? 'LOW' : d.depth < 8 ? 'MODERATE' : 'CRITICAL',
        Lat: d.lat,
        Lon: d.lon,
        Map: `https://www.google.com/maps?q=${d.lat},${d.lon}`,
      }));

    console.groupCollapsed(
      `%c🌊 ${risky.length} locations at risk (threshold ${level}m)`,
      'color:#ef4444;font-weight:bold'
    );
    console.table(risky);
    console.groupEnd();
  }, [floodData]);

  const handleLocateUser = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((p) => {
        const c = [p.coords.latitude, p.coords.longitude];
        setUserPos(c); setMapCenter(c);
      });
    }
  };

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Syncing satellite data</p></div>;

  const threshold = floodData?.current_water_level || 3.5;
  const isNormalState = threshold <= 3.0;
  const severeZones = floodData?.data?.filter(d => d.depth >= threshold) || [];
  const otherZones = floodData?.data?.filter(d => d.depth < threshold) || [];
  const currentSevere = severeZones.slice((severePage - 1) * ITEMS_PER_PAGE, severePage * ITEMS_PER_PAGE);

  const getAlert = (level) => {
    if (level < 3) return { title: "Conditions normal", message: "Water levels are within safe limits.", color: "#10b981", bg: "rgba(16, 185, 129, 0.1)", icon: "fa-check-circle" };
    if (level < 8) return { title: "Water rising", message: "Keep monitoring the basin.", color: "#f59e0b", bg: "rgba(245, 158, 11, 0.1)", icon: "fa-exclamation-circle" };
    return { title: "Flood warning", message: "Extreme risk detected downstream.", color: "#ef4444", bg: "rgba(239, 68, 68, 0.1)", icon: "fa-exclamation-triangle" };
  };

  const alertData = getAlert(threshold);
  const gaugePct = Math.max(0, Math.min(100, (threshold / GAUGE_MAX) * 100));

  return (
    <div className="rd-advanced-page">

      {/* 1. STICKY HEADER */}
      <header className="rd-nav-header">
        <button className="fm-brand" onClick={() => navigate('/river-forecast')}>
          <i className="fas fa-satellite-dish"></i>
          Periyar <span>Risk</span>
        </button>
        <button className="fm-btn" onClick={() => navigate('/river-forecast')}>
          <i className="fas fa-th-large"></i> Dashboard
        </button>
      </header>

      {/* 2. HERO — the reading shown against a staff gauge */}
      <section className="hero-section" style={{ '--hero-image': `url(${kaladyRiver})` }}>
        <div className="hero-copy">
          <span className="hero-tag">Geospatial intelligence</span>
          <h1>Flood risk across the Periyar basin</h1>
          <p className="hero-sub">
            Live hydrological simulation driven by the current river level at Kalady.
            Every point on the map below is a modelled water depth at that coordinate.
          </p>

          <div className="status-pill-container">
            <i className="fas fa-water" style={{ fontSize: '1.8rem', color: '#0e8a9e' }}></i>
            <div>
              <span className="pill-label">Current water level</span>
              <p className="pill-value">{threshold}m</p>
            </div>
            <i className={`fas ${alertData.icon}`} style={{ fontSize: '1.4rem', color: alertData.color }}></i>
          </div>
        </div>

        <div className="gauge" style={{ '--level': `${gaugePct}%` }} aria-hidden="true">
          <div className="gauge__post">
            <div className="gauge__water"></div>
          </div>
          <div className="gauge__mark gauge__mark--caution" style={{ '--at': `${(3 / GAUGE_MAX) * 100}%` }}><span>3m caution</span></div>
          <div className="gauge__mark gauge__mark--flood" style={{ '--at': `${(8 / GAUGE_MAX) * 100}%` }}><span>8m flood</span></div>
          <div className="gauge__reading" style={{ color: alertData.color }}>{threshold}m</div>
        </div>
      </section>

      {/* 3. MAP AREA */}
      <section className="map-section">
        <div className="map-alert-overlay" style={{ '--alert-color': alertData.color }}>
          <i className={`fas ${alertData.icon}`} style={{ color: alertData.color }}></i>
          <div>
            <h4>{alertData.title}</h4>
            <p>{alertData.message}</p>
          </div>
        </div>

        <CustomMapControls onSearch={(pos) => setMapCenter(pos)} onFindMe={handleLocateUser} />
        <MapLegend />

        <MapContainer center={[10.16, 76.43]} zoom={13} zoomControl={false} style={{ height: "100%", width: "100%" }}>
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png"
            attribution='&copy; OpenStreetMap &copy; CARTO'
          />
          {/* Moved off the top-left corner so it no longer sits under the search box */}
          <ZoomControl position="bottomleft" />
          <MapController targetLoc={mapCenter} />

          {userPos && (
            <CircleMarker center={userPos} radius={8} pathOptions={{ color: '#fff', weight: 2, fillColor: '#0b6e7f', fillOpacity: 1 }}>
              <Popup>Your location</Popup>
            </CircleMarker>
          )}

          {floodData?.data?.map((point, idx) => {
            const status = getRiskStatus(point.depth, isNormalState);
            return (
              <React.Fragment key={idx}>
                {/* Wide halo carries the click — a 6px dot is far too small to hit */}
                <CircleMarker
                  center={[point.lat, point.lon]}
                  radius={13}
                  className="flood-node"
                  pathOptions={{ stroke: false, fillColor: status.color, fillOpacity: 0.14 }}
                >
                  <Tooltip direction="top" offset={[0, -8]}>
                    <span style={{ color: status.color }}>{point.depth}m</span>
                  </Tooltip>
                  <Popup><LocationPopup {...point} isNormalState={isNormalState} /></Popup>
                </CircleMarker>

                {/* Visible core sits on top but ignores pointer events entirely */}
                <CircleMarker
                  center={[point.lat, point.lon]}
                  radius={5}
                  interactive={false}
                  className="flood-core"
                  pathOptions={{ color: '#fff', weight: 1.5, fillColor: status.color, fillOpacity: 1 }}
                />
              </React.Fragment>
            );
          })}
        </MapContainer>
      </section>

      {/* 4. CONTENT GRID */}
      <main className="main-content-grid">
        <div className="list-section">
          <h3 className="section-heading">
            <i className="fas fa-layer-group" style={{ color: '#0b6e7f' }}></i>
            Affected areas
            {!isNormalState && <span className="count">{severeZones.length} at or above {threshold}m</span>}
          </h3>

          {isNormalState ? (
            <div className="fm-empty">
              <i className="fas fa-check-circle"></i>
              <h4>No active flooding</h4>
              <p>River levels are within safe operational limits. Nothing needs attention right now.</p>
            </div>
          ) : (
            <div>
              {currentSevere.map((item, index) => <AffectedAreaItem key={index} data={item} index={index} />)}
              <Pagination currentPage={severePage} totalItems={severeZones.length} onPageChange={setSeverePage} />
            </div>
          )}
        </div>

        <div className="sidebar-section">
          <div className="rd-glass-card model-card">
            <h4>Model status</h4>
            <div className="model-state" style={{ '--state-color': isNormalState ? '#10b981' : '#ef4444' }}>
              <p>{isNormalState ? "Stable flow" : "Flood hazard alert"}</p>
            </div>
            <p className="model-note">
              Depths are modelled from satellite LiDAR topography combined with IoT water level
              sensors on the Periyar. Readings refresh with each sensor poll.
            </p>
          </div>
        </div>
      </main>

      <footer className="rd-footer">
        <p>© {new Date().getFullYear()} Center for AI-IoT Innovations. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default FloodMap;
